source = '''def transform(grid):
    h, w = len(grid), len(grid[0])

    # Full horizontal stripes encode a periodic sequence by row.
    stripe_rows = {r: row[0] for r, row in enumerate(grid)
                   if row[0] != 0 and all(v == row[0] for v in row)}
    if stripe_rows:
        period = len(stripe_rows)
        pattern = {}
        for r, color in stripe_rows.items():
            pattern[r % period] = color
        return [[pattern[r % period]] * w for r in range(h)]

    # Otherwise, the clues are segments of parallel anti-diagonals.
    clues = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                clues[r + c] = color
    period = len(clues)
    pattern = {d % period: color for d, color in clues.items()}
    return [[pattern[(r + c) % period] for c in range(w)] for r in range(h)]
'''
